CREATE OR REPLACE FUNCTION public.consume_ai_daily_quota(p_user_id uuid, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role text;
  v_limit integer;
  v_token_limit integer;
  v_used integer;
  v_tokens integer;
  v_request_id uuid;
  v_day timestamptz := date_trunc('day', now() at time zone 'utc') at time zone 'utc';
begin
  if p_user_id is null then
    raise exception 'user_required' using errcode = '22023';
  end if;
  select coalesce(p.role, 'user') into v_role from public.profiles p where p.id = p_user_id;
  v_role := coalesce(v_role, 'user');
  select l.daily_requests, l.daily_output_tokens into v_limit, v_token_limit
  from public.ai_usage_limits l where l.role = v_role limit 1;
  if v_limit is null then v_limit := 50; v_token_limit := 100000; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_user_id::text || ':' || v_day::text, 0)
  );
  select count(*)::integer, coalesce(sum(r.output_tokens), 0)::integer
  into v_used, v_tokens from public.ai_requests r
  where r.user_id = p_user_id and r.created_at >= v_day;
  if v_used >= v_limit or v_tokens >= v_token_limit then
    return jsonb_build_object('allowed', false, 'count', v_used, 'limit', v_limit,
      'tokens_used', v_tokens, 'token_limit', v_token_limit, 'error', 'daily_limit_reached');
  end if;
  insert into public.ai_requests(user_id, capability, status, routing_reason)
  values (p_user_id, 'chat', 'running', 'atomic_quota_reservation')
  returning id into v_request_id;
  return jsonb_build_object('allowed', true, 'count', v_used + 1, 'limit', v_limit,
    'tokens_used', v_tokens, 'token_limit', v_token_limit, 'request_id', v_request_id);
end
$function$

CREATE OR REPLACE FUNCTION public.submit_consultation_request(p_topic text, p_message text, p_related_application_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_topic text := nullif(btrim(p_topic), '');
  v_message text := nullif(btrim(p_message), '');
  v_request_id uuid;
  v_hour_count integer;
  v_day_count integer;
begin
  if v_user_id is null then raise exception 'authentication_required' using errcode = '42501'; end if;
  if v_topic is null or char_length(v_topic) not between 3 and 200 then raise exception 'invalid_consultation_topic' using errcode = '22023'; end if;
  if v_message is null or char_length(v_message) not between 10 and 5000 then raise exception 'invalid_consultation_message' using errcode = '22023'; end if;
  if p_related_application_id is not null and not exists (
    select 1 from public.applications a where a.id = p_related_application_id and a.user_id = v_user_id
  ) then raise exception 'related_application_forbidden' using errcode = '42501'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('consultation:' || v_user_id::text, 0));
  select count(*) filter (where c.created_at >= now() - interval '1 hour')::integer,
         count(*) filter (where c.created_at >= now() - interval '1 day')::integer
  into v_hour_count, v_day_count from public.consultation_requests c
  where c.user_id = v_user_id and c.created_at >= now() - interval '1 day';
  if v_hour_count >= 3 or v_day_count >= 10 then raise exception 'consultation_rate_limited' using errcode = 'P0001'; end if;
  insert into public.consultation_requests (user_id, topic, message, related_application_id, status)
  values (v_user_id, v_topic, v_message, p_related_application_id, 'submitted')
  returning id into v_request_id;
  return v_request_id;
end
$function$
